  "content": "1|import { useEffect, useState } from 'react';
2|import { EDGE_STATE_STORAGE_KEY } from '../constants';
3|import type { ServerFunctionCatalogState } from './useServerFunctionCatalog';
4|
5|type UseServerFunctionSettingsInput = {
6|  catalog: ServerFunctionCatalogState;
7|  addLog: (msg: string, type?: 'info' | 'success' | 'warn') => void;
8|};
9|
10|export function useServerFunctionSettings({ catalog, addLog }: UseServerFunctionSettingsInput) {
11|  const { activeId, functions } = catalog;
12|
13|  const [globalDefaultVMMode, setGlobalDefaultVMMode] = useState<'v18.x' | 'v20.x'>('v20.x');
14|  const [globalDefaultRAM, setGlobalDefaultRAM] = useState<number>(128);
15|  const [globalDefaultTimeout, setGlobalDefaultTimeout] = useState<number>(1500);
16|
17|  const [testVMMode, setTestVMMode] = useState<'v18.x' | 'v20.x'>('v20.x');
18|  const [testRAM, setTestRAM] = useState<number>(128);
19|  const [testTimeout, setTestTimeout] = useState<number>(1500);
20|
21|  const [isBulkOpen, setIsBulkOpen] = useState(false);
22|  const [bulkVMMode, setBulkVMMode] = useState<'v18.x' | 'v20.x'>('v20.x');
23|  const [bulkRAM, setBulkRAM] = useState<number>(128);
24|  const [bulkTimeout, setBulkTimeout] = useState<number>(1500);
25|
26|  useEffect(() => {
27|    if (activeId) {
28|      const active = functions.find((f) => f.id === activeId);
29|      if (active) {
30|        setTestVMMode(active.runtimeVersion);
31|        setTestRAM(active.memoryLimit);
32|        setTestTimeout(active.timeoutMs);
33|      }
34|    } else {
35|      setTestVMMode(globalDefaultVMMode);
36|      setTestRAM(globalDefaultRAM);
37|      setTestTimeout(globalDefaultTimeout);
38|    }
39|  }, [activeId, globalDefaultVMMode, globalDefaultRAM, globalDefaultTimeout, functions]);
40|
41|  useEffect(() => {
42|    try {
43|      const raw = localStorage.getItem(EDGE_STATE_STORAGE_KEY);
44|      if (!raw) return;
45|      const parsed = JSON.parse(raw);
46|      if (parsed?.globalDefaultVMMode === 'v18.x' || parsed?.globalDefaultVMMode === 'v20.x') {
47|        setGlobalDefaultVMMode(parsed.globalDefaultVMMode);
48|      }
49|      if (typeof parsed?.globalDefaultRAM === 'number') {
50|        setGlobalDefaultRAM(parsed.globalDefaultRAM);
51|      }
52|      if (typeof parsed?.globalDefaultTimeout === 'number') {
53|        setGlobalDefaultTimeout(parsed.globalDefaultTimeout);
54|      }
55|    } catch {
56|      addLog('Stored edge settings were invalid and were ignored.', 'warn');
57|    }
58|  }, [addLog]);
59|
60|  return {
61|    globalDefaultVMMode,
62|    setGlobalDefaultVMMode,
63|    globalDefaultRAM,
64|    setGlobalDefaultRAM,
65|    globalDefaultTimeout,
66|    setGlobalDefaultTimeout,
67|    testVMMode,
68|    setTestVMMode,
69|    testRAM,
70|    setTestRAM,
71|    testTimeout,
72|    setTestTimeout,
73|    isBulkOpen,
74|    setIsBulkOpen,
75|    bulkVMMode,
76|    setBulkVMMode,
77|    bulkRAM,
78|    setBulkRAM,
79|    bulkTimeout,
80|    setBulkTimeout,
81|  };
82|}
83|
84|export type ServerFunctionSettingsState = ReturnType<typeof useServerFunctionSettings>;
85|"
